
// Find the shared collection dialog.
const collectionDialog = document.getElementById("collectionDialog");

// Only run this script on pages that contain the dialog.
if (collectionDialog) {
    const collectionSelect = document.getElementById("collectionSelect");
    const collectionMessage = document.getElementById("collectionMessage");
    const collectionForm = document.getElementById("addToCollectionForm");
    const saveButton = document.getElementById("saveCollectionButton");
    const closeButton = document.getElementById("closeDialog");

    // Get the URLs generated by Razor in the shared partial.
    const collectionsUrl = collectionDialog.dataset.collectionsUrl;
    const addUrl = collectionDialog.dataset.addUrl;

    // When an Add to Collection button is clicked...
    document.addEventListener("click", async function (event) {
        const button = event.target.closest(".add-to-collection");

        if (!button) {
            return;
        }

        // Store the selected item's ID and type.
        document.getElementById("selectedItemId").value =
            button.dataset.itemId;

        document.getElementById("selectedItemType").value =
            button.dataset.itemType;

        // Reset the dialog.
        collectionMessage.textContent = "";
        collectionSelect.innerHTML =
            '<option value="">Loading collections...</option>';

        collectionDialog.showModal();

        try {
            // Request the logged-in user's collections.
            const response = await fetch(collectionsUrl);

            if (!response.ok) {
                throw new Error("Could not load collections.");
            }

            const collections = await response.json();

            collectionSelect.innerHTML = "";

            if (collections.length === 0) {
                collectionSelect.add(
                    new Option("You have no collections yet", "")
                );

                collectionMessage.textContent =
                    "Create a collection before adding items.";

                return;
            }

            collectionSelect.add(
                new Option("Select a collection...", "")
            );

            // Add each collection as a dropdown option.
            collections.forEach(collection => {
                collectionSelect.add(
                    new Option(collection.name, collection.id)
                );
            });
        }
        catch (error) {
            collectionSelect.innerHTML =
                '<option value="">Unable to load collections</option>';

            collectionMessage.textContent =
                "Please try again.";
        }
    });

    // Close the dialog.
    closeButton.addEventListener("click", function () {
        collectionDialog.close();
    });

    // Handle the form submission.
    collectionForm.addEventListener("submit", async function (event) {
        event.preventDefault();

        const collectionId = collectionSelect.value;
        const itemId =
            document.getElementById("selectedItemId").value;
        const itemType =
            document.getElementById("selectedItemType").value;

        if (!collectionId) {
            collectionMessage.textContent =
                "Please select a collection.";

            return;
        }

        // Retrieve the anti-forgery token.
        const token = collectionForm.querySelector(
            'input[name="__RequestVerificationToken"]'
        ).value;

        // Prepare the data being sent to the controller.
        const body = new URLSearchParams({
            id: itemId,
            type: itemType,
            collectionId: collectionId
        });

        saveButton.disabled = true;
        collectionMessage.textContent = "Adding item...";

        try {
            const response = await fetch(addUrl, {
                method: "POST",
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded",
                    "RequestVerificationToken": token
                },
                body: body
            });

            if (!response.ok) {
                const message = await response.text();
                throw new Error(message || "Could not add the item.");
            }

            collectionMessage.textContent =
                "Added to collection successfully!";

            setTimeout(function () {
                collectionDialog.close();
            }, 800);
        }
        catch (error) {
            collectionMessage.textContent =
                error.message || "Unable to add this item. Please try again.";
        }
        finally {
            saveButton.disabled = false;
        }
    });
}
